// Lay du lieu tu webhook va query truoc do
const webhookData = $('Webhook - Receive Status Change').first().json.body;
const taskData = $input.first().json;

// Tinh lead time (chi khi status = DONE)
let lead_time_hours = null;

if (webhookData.new_status === 'DONE') {
  const createdAt = new Date(taskData.created_at);
  const now = new Date();
  lead_time_hours = Math.round(
    ((now.getTime() - createdAt.getTime()) / (1000 * 60 * 60)) * 100
  ) / 100;
}

return [{
  json: {
    task_id: webhookData.task_id,
    task_title: webhookData.task_title,
    project_id: webhookData.project_id,
    old_status: webhookData.old_status,
    new_status: webhookData.new_status,
    changed_by: webhookData.changed_by || null,
    lead_time_hours: lead_time_hours,
    timestamp: webhookData.timestamp,
    message: lead_time_hours
      ? 'Task hoan thanh! Lead time: ' + lead_time_hours + ' gio'
      : webhookData.old_status + ' -> ' + webhookData.new_status
  }
}];
